param([string]$RepositoryRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'Stage3StaticAudit.Common.ps1')
$records = @(Get-AICFSourceRecords $RepositoryRoot)
$failures = [Collections.Generic.List[string]]::new()
$negativeCount = 0
function Method([string]$File, [string]$Name) {
    $record = $records | Where-Object Name -eq $File
    if (@($record).Count -ne 1) { throw "Ожидался один production source: $File" }
    (ConvertTo-AICFCodeText (Get-AICFMethodBody $record $Name)) -replace '\s+', ' '
}
function Require([string]$Rule, [string]$Code, [string]$Pattern, [string]$Remove = '') {
    Assert-AICFContains $failures $Rule $Code $Pattern 'AI loadout contract'
    if ($Remove) {
        if (-not $Code.Contains($Remove)) { throw "Нет отрицательной мутации $Rule" }
        if ($Code.Replace($Remove, '') -match $Pattern) { $failures.Add("[$Rule] Отрицательная копия не отклонена") }
        $script:negativeCount++
    }
}
$context = Method 'AICF_MatchController.c' 'ResolveLoadoutContext'
Require 'LOADOUT_AUTHORITY' $context '!Replication.IsServer\(\)' '!Replication.IsServer()'
Require 'LOADOUT_PLAYER_OWNER' $context 'GetPlayerController\(player.GetPlayerId\(\)\) != player' 'GetPlayerController(player.GetPlayerId()) != player'
Require 'LOADOUT_FACTION' $context 'SGetPlayerFaction\(player.GetPlayerId\(\)\)' 'SGetPlayerFaction(player.GetPlayerId())'
Require 'LOADOUT_MATCH_GATE' $context '!m_bRosterReady.*!m_Campaign.IsMaster\(\).*!m_Campaign.IsRunning\(\)' '!m_Campaign.IsMaster()'
Require 'LOADOUT_MEMBER_BOUND' $context 'member >= slot.GetDesiredSize\(\)' 'member >= slot.GetDesiredSize()'
