Require 'LOADOUT_CONTENT_BOUNDARY' $request 'candidate.m_sProfile == recipe.m_sProfile.*candidate.m_sFaction == recipe.m_sFaction.*candidate.m_sCharacter == source' 'candidate.m_sCharacter == source'
Require 'LOADOUT_REVISION' $request 'revision != slot.GetLoadoutRevision\(\)' 'revision != slot.GetLoadoutRevision()'
Require 'LOADOUT_SAVE_BEFORE_BIND' $request 'm_Store.Save\(candidate, reason\).*slot.SetLoadout\(member, binding, revision\)' 'm_Store.Save(candidate, reason)'
