Require 'LOADOUT_PAYLOAD_BOUND' $rpc 'payload.Length\(\) > AICF_LoadoutRecipe.MAX_BYTES' 'payload.Length() > AICF_LoadoutRecipe.MAX_BYTES'
Require 'LOADOUT_RATE_LIMIT' $rpc 'now < m_iAICFLoadoutRateAt.*m_iAICFLoadoutRateAt = now \+ 750' 'now < m_iAICFLoadoutRateAt'
