Require 'LOADOUT_ARRAY_BOUNDS' $bounds 'count > MAX_OPERATIONS.*m_aCounts.Count\(\) != count.*m_aPrefabs.Count\(\) != count' 'm_aCounts.Count() != count'
Require 'LOADOUT_QUANTITY_BOUNDS' $bounds 'm_aCounts\[i\] < 1 \|\| m_aCounts\[i\] > 16' 'm_aCounts[i] > 16'
Require 'LOADOUT_DEPTH_BOUND' $bounds 'segments.Count\(\) > 6' 'segments.Count() > 6'
