Require 'LOADOUT_GRID_NO_SELECTION_JUMP' $items 'sameItems = m_Items.SetItems\(m_aItems, names, details, true\).*m_Items.Select\(m_aItems.Find\(previous\), !sameItems\)' '!sameItems'
Require 'LOADOUT_GRID_EMPTY_STATE' (Method 'AICF_LoadoutItemGrid.c' 'Render') 'm_Empty.SetVisible\(m_aPrefabs.IsEmpty\(\)\)' 'm_Empty.SetVisible(m_aPrefabs.IsEmpty())'
Require 'LOADOUT_AREA_METADATA_CACHE' (Method 'AICF_LoadoutSlotView.c' 'Get') 'm_Areas.Find\(prefab, area\).*ResolvePreviewEntityForPrefab.*GetWorld\(\) == GetGame\(\).GetWorld\(\).*m_Areas.Insert' 'm_Areas.Find(prefab, area)'
$gridRecord = $records | Where-Object Name -eq 'AICF_LoadoutItemGrid.c'
Assert-AICFNotContains $failures 'LOADOUT_CARD_NO_MUTABLE_DRAFT' $gridRecord.Code 'array<IEntity>|ResolvePreviewEntityForPrefab|m_Draft|delete m_Manager' 'Миниатюры используют prefab-only cache штатного UI; черновик остаётся изолированным'
Assert-AICFNotContains $failures 'LOADOUT_CARD_SRGB_PALETTE' (Method 'AICF_LoadoutItemGrid.c' 'RefreshColors') 'Color.FromInt' 'Палитра карточек использует тот же SRGBA путь, что и панель'
Require 'LOADOUT_PREVIEW_FAILURE_VISIBLE' (Method 'AICF_LoadoutEditor.c' 'Refresh') 'if \(!Rebuild\(\)\) status =' '!Rebuild()'
Require 'LOADOUT_IDLE_ROTATION' (Method 'AICF_LoadoutEditor.c' 'RotatePreview') 'if \(x == m_iMouseX && y == m_iMouseY\) return;' 'if (x == m_iMouseX && y == m_iMouseY) return;'
Require 'LOADOUT_ACTIVATION_CLEANUP' (Method 'AICF_LoadoutEditor.c' 'Close') 'm_OnActivated.Remove\(OnItemActivated\)' 'm_OnActivated.Remove(OnItemActivated)'
Require 'LOADOUT_DOUBLE_CLICK_GATE' (Method 'AICF_LoadoutItemGrid.c' 'OnDoubleClick') '!m_bEnabled.*SCR_EMouseButtons.LEFT.*index >= m_aPrefabs.Count\(\).*m_OnActivated.Invoke' '!m_bEnabled'
Require 'LOADOUT_ACTIVATION_SHARED_APPLY' (Method 'AICF_LoadoutEditor.c' 'OnItemActivated') 'grid != m_Items.*ApplySelection\(false\)' 'ApplySelection(false)'
Require 'LOADOUT_APPLY_PENDING_GATE' (Method 'AICF_LoadoutEditor.c' 'ApplySelection') 'm_bPending \|\| !m_Recipe \|\| !m_bDraftReady' 'm_bPending || '
Require 'LOADOUT_SAVE_CHANGED_AND_VALID' (Method 'AICF_LoadoutEditor.c' 'OnClick') '!HasDraftChanges\(\) \|\| !HasValidName\(\) \|\| m_Player.AICF_LoadoutRevision\(\) != m_iRevision.*Request\(1, m_Recipe.Encode\(\)\)' '!HasDraftChanges() || '
Require 'LOADOUT_DIRTY_TARGET_RESET' (Method 'AICF_LoadoutEditor.c' 'SelectTarget') 'm_sAppliedData = string.Empty; m_sDraftData = string.Empty;' 'm_sDraftData = string.Empty;'
Require 'LOADOUT_NAME_INPUT_CLEANUP' (Method 'AICF_LoadoutEditor.c' 'Close') 'if \(m_wName\) m_wName.RemoveHandler\(this\)' 'm_wName.RemoveHandler(this)'
Require 'LOADOUT_APPLY_ROLLBACK' (Method 'AICF_LoadoutEditor.c' 'ApplySelection') 'if \(!Rebuild\(\)\).*m_Recipe.Undo\(\).*Rebuild\(\)' 'm_Recipe.Undo()'
Require 'LOADOUT_CAPACITY_NATIVE' (Method 'AICF_LoadoutSlotView.c' 'Capacity') 'GetOwnedStorages\(pockets, 1, false\).*GetOccupiedSpace\(\).*GetMaxVolumeCapacity\(\)' 'GetOwnedStorages(pockets, 1, false)'
Require 'LOADOUT_VIEW_CLEANUP' (Method 'AICF_LoadoutEditor.c' 'Close') 'm_wRoot.RemoveFromHierarchy\(\).*m_Preview.Clear\(\)' 'm_Preview.Clear()'
Require 'LOADOUT_NO_GAMEPLAY_RENDER' (Method 'AICF_LoadoutEditor.c' 'Rebuild') 'm_wPreview.SetVisible\(false\).*m_wPreview.SetWorld.*m_wPreview.SetVisible\(true\)' 'm_wPreview.SetWorld(m_Preview.GetWorld(), 0)'
$rect = Method 'AICF_StrategicUI.c' 'CreateRect'
Require 'LOADOUT_BACKGROUND_INPUT_TRANSPARENCY' $rect 'background.SetFlags\(WidgetFlags.VISIBLE \| WidgetFlags.IGNORE_CURSOR' 'background.SetFlags(WidgetFlags.VISIBLE | WidgetFlags.IGNORE_CURSOR'
Require 'LOADOUT_BACKGROUND_COLOR_VALUE' $rect 'backgroundColor = color.PackToInt\(\).*background.SetColor\(Color.FromInt\(backgroundColor\)\)' 'background.SetColor(Color.FromInt(backgroundColor))'
Require 'LOADOUT_BACKGROUND_LAYER' $rect 'background.SetZOrder\(0\).*inputWidget.SetZOrder\(1\)' 'background.SetZOrder(0)'
Require 'LOADOUT_LOCAL_LIGHTS' (Method 'AICF_LoadoutPreview.c' 'Build') 'm_Lighting = GetGame\(\).SpawnEntityPrefabLocal\(lighting, m_World\).*if \(!HasLighting\(\)\)' 'if (!HasLighting())'
Require 'LOADOUT_LIGHTS_CLEANUP' (Method 'AICF_LoadoutPreview.c' 'Clear') 'DeleteEntityAndChildren\(m_Lighting\).*m_Lighting = null.*m_WorldRef = null' 'DeleteEntityAndChildren(m_Lighting)'
$fill = Method 'AICF_LoadoutPreview.c' 'CreateFillLight'
Require 'LOADOUT_FILL_OWN_WORLD' $fill 'SpawnEntityPrefabLocal\(resource, m_World\).*entity.GetWorld\(\) != m_World.*DeleteEntityAndChildren\(entity\)' 'entity.GetWorld() != m_World'
Require 'LOADOUT_FILL_NO_SHADOW_PASS' $fill 'SetCastShadow\(false\)' 'SetCastShadow(false)'
Require 'LOADOUT_FILL_CLEANUP' (Method 'AICF_LoadoutPreview.c' 'Clear') 'DeleteEntityAndChildren\(m_FillLight\).*m_FillLight = null.*m_WorldRef = null' 'DeleteEntityAndChildren(m_FillLight)'
$fillUpdate = Method 'AICF_LoadoutPreview.c' 'UpdateFillLight'
Require 'LOADOUT_FILL_ENTITY_ORIENTATION' $fillUpdate 'DirectionAndUpMatrix\(direction, camera\[1\], lightTransform\).*lightTransform\[3\] = position.*SetWorldTransform\(lightTransform\).*m_FillLight.Update\(\)' 'SetWorldTransform(lightTransform)'
Assert-AICFNotContains $failures 'LOADOUT_NO_FILL_REBUILD_ON_INPUT' (Method 'AICF_LoadoutPreview.c' 'UpdateFillLight') 'SpawnEntity|CreateLight|Resource.Load' 'Input меняет transform существующего света'
Assert-AICFNotContains $failures 'LOADOUT_NO_FILL_REQUIRED_FOR_MODEL' (Method 'AICF_LoadoutPreview.c' 'IsReady') 'HasFillLight|m_FillLight' 'При недоступной дополнительной подсветке остаётся stock scene'
$previewRecord = $records | Where-Object Name -eq 'AICF_LoadoutPreview.c'
$nativePointerField = '\bLightHandle\s+m_\w+'
Assert-AICFNotContains $failures 'LOADOUT_NO_NATIVE_POINTER_FIELDS' $previewRecord.Code $nativePointerField 'LightHandle допускается только как локальная переменная'
$invalidField = $previewRecord.Code + ' protected LightHandle m_InvalidLight;'
if ($invalidField -notmatch $nativePointerField) { $failures.Add('[LOADOUT_NO_NATIVE_POINTER_FIELDS] Отрицательная копия не отклонена') }
$negativeCount++
Assert-AICFNotContains $failures 'LOADOUT_NO_ROTATION_REBUILD' (Method 'AICF_LoadoutEditor.c' 'RotatePreview') 'SetPreviewItem|\.Build\(' 'Вращение меняет только камеру'
Require 'LOADOUT_SAVE_ACK' (Method 'AICF_LoadoutEditor.c' 'Refresh') 'AICF_LoadoutToken\(\) == m_iToken.*AICF_LoadoutAccepted\(\)' 'AICF_LoadoutAccepted()'
Require 'LOADOUT_DEPLOYMENT_REVISION' (Method 'AICF_GroupSlot.c' 'ApplyDeploymentLoadouts') '!IsDeploymentLoadoutCurrent\(\)' '!IsDeploymentLoadoutCurrent()'
foreach ($spawn in @('BeginInitialSpawn', 'BeginReplacementSpawn')) {
    Require "LOADOUT_$spawn" (Method 'AICF_GroupSlot.c' $spawn) 'm_iDeploymentLoadoutRevision = m_iLoadoutRevision;.*m_iSpawnGeneration\+\+' 'm_iDeploymentLoadoutRevision = m_iLoadoutRevision;'
}
$tick = Method 'AICF_InfantryRecruitmentService.c' 'Tick'
Require 'LOADOUT_RECRUIT_BASE_PRICE' $tick 'order.m_iCost = m_Config.Cost\(order.m_sRole\);' 'order.m_iCost = m_Config.Cost(order.m_sRole);'
$recruitment = ($records | Where-Object Name -eq 'AICF_InfantryRecruitmentService.c').Code
Assert-AICFNotContains $failures 'LOADOUT_RECRUIT_NO_SURCHARGE' $recruitment '(loadout|binding).m_iCost|order.m_iCost\s*\+=' 'Комплект не меняет выбор казармы или цену роли'
$economy = ($records | Where-Object Name -eq 'AICF_EconomySystem.c').Code
Assert-AICFNotContains $failures 'LOADOUT_REPLACEMENT_NO_SURCHARGE' $economy 'GetDeploymentLoadoutCost\(' 'Цена, pacing и reservation replacement не зависят от экипировки'
foreach ($negative in @(
    @($recruitment + ' cost += binding.m_iCost;', '(loadout|binding).m_iCost|order.m_iCost\s*\+='),
    @($economy + ' slot.GetDeploymentLoadoutCost();', 'GetDeploymentLoadoutCost\(')
)) {
    if ($negative[0] -notmatch $negative[1]) { $failures.Add('[LOADOUT_NO_SURCHARGE] Отрицательная копия не отклонена') }
    $negativeCount++
}
Require 'LOADOUT_RECRUIT_REVISION' $tick 'order.m_iLoadoutRevision != order.m_Slot.GetLoadoutRevision\(\)' 'order.m_iLoadoutRevision != order.m_Slot.GetLoadoutRevision()'
Require 'LOADOUT_RECRUIT_BEFORE_DEBIT' $tick 'HasExactFactionRoster.*AICF_LoadoutApplicator.Apply.*DebitInfantryRecruit.*RefundInfantryRecruit' 'AICF_LoadoutApplicator.Apply'
Require 'LOADOUT_SPAWN_INDEX' (Method 'AICF_LoadoutMemberIdentity.c' 'SpawnGroupMember') 'super.SpawnGroupMember.*!before.Contains\(agent\).*added == 1.*m_aUnitPrefabSlots\[index\] == res' 'added == 1'
foreach ($record in $records | Where-Object { $_.Name -like 'AICF_Loadout*' }) {
    Assert-AICFNotContains $failures 'LOADOUT_NO_RAW_SERIALIZER' $record.Code 'ApplyLoadoutString\(' 'Внешний payload не является stock snapshot'
    if ($record.Name -like '*Probe*') { $failures.Add('[LOADOUT_FIXTURE_IN_PRODUCTION] Удалить временный probe') }
}
if ($failures.Count) {
    $failures | ForEach-Object { Write-Output "[AICF][LOADOUT_STATIC][FAIL] $_" }
    exit 1
}
Write-Output "[AICF][LOADOUT_STATIC][PASS] negative_cases=$negativeCount authority=PASS identity=PASS inventory=PASS persistence=PASS lifecycle=PASS"
exit 0
